import React, { useContext } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import LandingPage from './components/LandingPage';
import Visualization from './components/Visualization';
import Prediction from './components/Prediction';
import Login from './components/Login';
import Signup from './components/Signup';
import { AppProvider, AppContext } from './components/AppContext'; 
import './App.css';

function AppRoutes() {
  const { token, setToken } = useContext(AppContext);

  const PrivateRoute = ({ children }) => (token ? children : <Navigate to="/login" />);
  const PublicRoute = ({ children }) => (!token ? children : <Navigate to="/landing" />);

  return (
    <Routes>
      <Route path="/" element={token ? <Navigate to="/landing" /> : <Navigate to="/login" />} />

      {/* Public Pages */}
      <Route path="/login" element={<PublicRoute><Login onLogin={setToken} /></PublicRoute>} />
      <Route path="/signup" element={<PublicRoute><Signup /></PublicRoute>} />

      {/* Private Pages */}
      <Route path="/landing" element={<PrivateRoute><LandingPage onLogout={() => setToken(null)} /></PrivateRoute>} />
      <Route path="/visualization" element={<PrivateRoute><Visualization /></PrivateRoute>} />
      <Route path="/prediction" element={<PrivateRoute><Prediction token={token} /></PrivateRoute>} />

      {/* Catch all */}
      <Route path="*" element={<Navigate to="/" />} />
    </Routes>
  );
}

function App() {
  return (
    <AppProvider>
      <Router>
        <div className="app-container">
          <AppRoutes />
        </div>
      </Router>
    </AppProvider>
  );
}

export default App;
